  match r, ph with
  | 1, 0 => farm1_0_0RB1LA_1LA1RC_1RD0LA_1RB1RB
  | _, _ => farm1_0_0RB1LA_1LA1RC_1RD0LA_1RB1RB  (* unreachable: 0 < r < N0 + st *)
  end.

