  check_arm tm true false rules iarm0_0_0RB1LA_1LC1RC_1RB0LA_______
            ch_iarm0_0_0RB1LA_1LC1RC_1RB0LA_______ = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_0RB1LA_1LC1RC_1RB0LA_______ (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LA_1LC1RC_1RB0LA_______
  | _, _ => iarm0_0_0RB1LA_1LC1RC_1RB0LA_______   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_0RB1LA_1LC1RC_1RB0LA_______ : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [S1;S0] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [] [S1;S1] 1 0 [S1;S0;S1])) 4 6.
