(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_0RB1LA_1LC1RD_1LD1RB_1RC0LA : NeverQuasiHaltsTr tm_0RB1LA_1LC1RD_1LD1RB_1RC0LA.
Proof.
  apply (boardph_neverqhtr tm_0RB1LA_1LC1RD_1LD1RB_1RC0LA pins_0RB1LA_1LC1RD_1LD1RB_1RC0LA FAM 1
