  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => [SWin 5;SCycR 5;SWinR 6]
  | 1, (StB, S0) => [SWin 5;SCycR 5;SWinR 4]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 5]
  | 1, (StC, S1) => [SWin 5;SCycR 5;SWinR 5]
  | 1, (StD, S0) => [SWin 4]
  | 1, (StD, S1) => [SWin 2]
  | _, _ => []
  end.

