Import LadderCheckLiftTr.
Import ListNotations.

Definition mk_0RB1LA_1LC1RD_1RB0LA_1RC1RC (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_0RB1LA_1LC1RD_1RB0LA_1RC1RC.

(** 0RB1LA_1LC1RD_1RB0LA_1RC1RC *)
Definition tm_0RB1LA_1LC1RD_1RB0LA_1RC1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB
  | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DL StC
  | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DR StB
  | StC, S1 => mk S0 DL StA
  | StD, S0 => mk S1 DR StC
  | StD, S1 => mk S1 DR StC
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB1LA_1LC1RD_1RB0LA_1RC1RC : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_0RB1LA_1LC1RD_1RB0LA_1RC1RC pins_0RB1LA_1LC1RD_1RB0LA_1RC1RC).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB1LA_1LC1RD_1RB0LA_1RC1RC : Fam := mkFam 2 [[S1;S1;S1];[S1;S1;S0]] [] [[S1]] Binary 1 [mkFill 1 [] 0 [1] 0] StA S0 false [].
Local Notation FAM := fam_0RB1LA_1LC1RD_1RB0LA_1RC1RC.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1LA_1LC1RD_1RB0LA_1RC1RC : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S1;S1] [] 0 0 [])) (mkC StD (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S1;S1] [] 0 0 [])) (mkC StD (mkS [S1;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_0RB1LA_1LC1RD_1RB0LA_1RC1RC.

Definition rules_0RB1LA_1LC1RD_1RB0LA_1RC1RC : list LRule := map fst lad.
Local Notation rules := rules_0RB1LA_1LC1RD_1RB0LA_1RC1RC.

Lemma ladder_ok_0RB1LA_1LC1RD_1RB0LA_1RC1RC : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LA_1LC1RD_1RB0LA_1RC1RC : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LA_1LC1RD_1RB0LA_1RC1RC. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
