Lemma farm_sound_0RB1LA_1RC0LA_1LB1RB_______ : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_0RB1LA_1RC0LA_1LB1RB_______ r ph).
