Lemma farm_lhs_0RB1LA_1RC0LA_1LB1RB_______ : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_lhs (farm_0RB1LA_1RC0LA_1LB1RB_______ r ph)
    = cls_conf FAM (run_side FAM (fm_b FAM - 1) r (astride 1 1 r)
                      0 ph [] []).
Proof.
