Lemma farm_sound_0RB1LA_1RC0LA_1LB1RD_1RB0LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_0RB1LA_1RC0LA_1LB1RD_1RB0LC r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
