(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_0RB1LA_1RC1RC_1RD0LA_1LA1RB : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_0RB1LA_1RC1RC_1RD0LA_1LA1RB pins_0RB1LA_1RC1RC_1RD0LA_1LA1RB).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_0RB1LA_1RC1RC_1RD0LA_1LA1RB : Fam := mkFam 2 [[S1;S1;S1];[S1;S0;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [] 0] StA S0 false [].
Local Notation FAM := fam_0RB1LA_1RC1RC_1RD0LA_1LA1RB.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1LA_1RC1RC_1RD0LA_1LA1RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [] 0 0 [])) (mkC StC (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S0] [] 0 0 [])) (mkC StC (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3)])].
Local Notation lad := lad_0RB1LA_1RC1RC_1RD0LA_1LA1RB.

Definition rules_0RB1LA_1RC1RC_1RD0LA_1LA1RB : list LRule := map fst lad.
Local Notation rules := rules_0RB1LA_1RC1RC_1RD0LA_1LA1RB.

Lemma ladder_ok_0RB1LA_1RC1RC_1RD0LA_1LA1RB : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LA_1RC1RC_1RD0LA_1LA1RB : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LA_1RC1RC_1RD0LA_1LA1RB. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* A[0] L<> R<1^3+y0>  ==>  A[0] L<> R<1^1 0^1 1^1+y0>   [4 steps] *)
Definition arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB : LRule :=
  mkLRule (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1] 1 0 []))
          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S1;S0;S1] [S1] 1 0 [])) 0 4.
Definition ch_arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB : list rstep := [RB (SWin 4)].
Lemma ok_arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB :
  check_arm tm true true rules arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB ch_arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB : RuleSound tm true true arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB.
Proof. eapply arm_sound; [exact rules_sound_0RB1LA_1RC1RC_1RD0LA_1LA1RB | exact ok_arm6_0RB1LA_1RC1RC_1RD0LA_1LA1RB]. Qed.

