(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_0RB1LA_1RC1RC_1RD0LA_1LC1RB : NeverQuasiHaltsTr tm_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
Proof.
  apply (boardph_neverqhtr tm_0RB1LA_1RC1RC_1RD0LA_1LC1RB pins_0RB1LA_1RC1RC_1RD0LA_1LC1RB FAM 1
                           iarm_0RB1LA_1RC1RC_1RD0LA_1LC1RB 0 1
                           farm_0RB1LA_1RC1RC_1RD0LA_1LC1RB 1 1
                           fm1_0RB1LA_1RC1RC_1RD0LA_1LC1RB fm2_0RB1LA_1RC1RC_1RD0LA_1LC1RB 0 vis_0RB1LA_1RC1RC_1RD0LA_1LC1RB
                           [1] 0 6).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - lia.
  - exact iarm_sound_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - exact iarm_lhs_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - exact iarm_rhs_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - exact iarm_cb_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - lia.
  - lia.
  - exact farm_sound_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - exact farm_lhs_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - exact farm_rhs_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - exact farm_cb_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
  - exact vis_ok_0RB1LA_1RC1RC_1RD0LA_1LC1RB.
Qed.

